        <div className={cn("mt-2 flex h-11 overflow-hidden rounded-xl", s.vorhang, s.laden)} style={{ "--ov-delay": "520ms" }} role="img" aria-label={`Heute: ${teile.map((t) => `${t.label} ${fmt(t.ct, 1)} ct`).join(", ")}`}>
          {teile.map((t) => (
            <span key={t.id} className={cn("flex h-full items-center justify-center border-r-2 border-white last:border-r-0", FARBEN[t.id])} style={{ width: pct(t.ct) }}>
              {t.ct > 1.5 && <span >{fmt(t.ct, 1)}</span>}
            </span>
          ))}
        </div>
      </div>

      {/* Im Pool */}
      <div >
        <div >
          <span >Im Pool</span>
          <span >
            {fmt(summe - hebelMax, 1)}–{fmt(summe - hebelMin, 1)}
          </span>
        </div>
        <div className={cn("mt-2 flex h-11 overflow-hidden rounded-xl", s.vorhang, s.laden)} style={{ "--ov-delay": "980ms" }} role="img" aria-label={`Im Pool: Beschaffung um ${fmt(hebelMin, 1)} bis ${fmt(hebelMax, 1)} ct niedriger, feste Bestandteile unverändert`}>
          <span className={cn("flex h-full items-center justify-center", FARBEN.beschaffung)} style={{ width: pct(beschaffung.ct - hebelMax) }}>
            <span >Beschaffung</span>
          </span>
          <span  style={{ width: pct(hebelMax - hebelMin) }} />
          {fix.map((t) => (
            <span key={t.id} className={cn("h-full border-r-2 border-white last:border-r-0", FARBEN[t.id])} style={{ width: pct(t.ct) }} />
          ))}
          <span  style={{ width: pct(hebelMin) }}>
            <span >Ersparnis</span>
          </span>
        </div>
        <div  aria-hidden="true">
          <span ><span  />Spanne je nach Profil</span>
          <span ><span  />mindestens eingespart</span>
          <span ><span  />fest: Netz, Umlagen, Steuer</span>
        </div>
      </div>

      {/* Hebel */}
      <ul >
        {STROM.poolHebel.map((h) => {
          const Icon = HEBEL_ICONS[h.id] || Handshake;
          return (
            <li key={h.id} >
              <span aria-hidden="true" ><Icon  /></span>
              <span >
                <span >{KURZ[h.id] || h.label}</span>
                <span >−{fmt(h.ct.min, 1)} bis −{fmt(h.ct.max, 1)} ct</span>
              </span>
            </li>
          );
        })}
      </ul>
      <p >Grobe Aufteilung (BDEW-Strompreisanalyse, eigene Einschätzung). Die Pool-Hebel wirken nur auf die Beschaffung, je nach Profil, Menge und Marktlage.</p>
    </figure>
  );
}
